syntax:
// program.cpp   (source code, written by you)
//    |  preprocessor adds #include files
//    v  compiler translates (syntax errors appear here)
// program.obj   (object code, not runnable yet)
//    |  linker adds library code (like cout)
//    v
// program.exe   (machine code / executable)
//    |  loader puts it in RAM, CPU runs it (runtime errors appear here)
//    v
// output on screen (wrong answer? a logical error)
//
// Compile with g++:  g++ program.cpp -o program

sample.code:
#include <iostream>
using namespace std;

int main() {
    cout << "Compiled and running!" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a = 10;
    int b = 20;
    int average = a + b / 2;
    cout << "Average = " << average << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a, b;
    cout << "Enter two marks: ";
    cin >> a >> b;
    double average = (a + b) / 2.0;
    cout << "Average = " << average << endl;
    return 0;
}

